#include <map>
#include <string>
#include <vector>

struct Call { std::string name; bool result{ true }; };

std::string checkFrame(const std::vector<Call>& calls)
{
    static const std::map<std::string, std::string> endOf{
        { "Begin", "End" }, { "BeginChild", "EndChild" }, { "BeginTable", "EndTable" }, { "BeginMenu", "EndMenu" }, { "PushID", "PopID" },
    };
    static const std::map<std::string, std::string> beginOf{
        { "End", "Begin" }, { "EndChild", "BeginChild" }, { "EndTable", "BeginTable" }, { "EndMenu", "BeginMenu" }, { "PopID", "PushID" },
    };
    struct Open { std::string name; int at; };
    std::vector<Open> open;
    // Begin calls that returned false and therefore need no end: remembered so that a wrong end can be named.
    std::vector<Open> skipped;
    for (int i{ 0 }; i < static_cast<int>(calls.size()); ++i)
    {
        const Call& c{ calls[static_cast<std::size_t>(i)] };
        if (endOf.count(c.name))
        {
            const bool conditional{ c.name == "BeginTable" || c.name == "BeginMenu" };
            if (conditional && !c.result) skipped.push_back({ c.name, i });
            else open.push_back({ c.name, i });
            continue;
        }
        const auto b{ beginOf.find(c.name) };
        if (b == beginOf.end()) continue;
        if (!open.empty() && open.back().name == b->second) { open.pop_back(); continue; }
        for (auto it{ skipped.rbegin() }; it != skipped.rend(); ++it)
            if (it->name == b->second) return c.name + " at " + std::to_string(i) + " was called although " + b->second + " returned false";
        return c.name + " at " + std::to_string(i) + " has no matching " + b->second;
    }
    if (!open.empty()) return "missing " + endOf.at(open.back().name) + " for " + open.back().name + " at " + std::to_string(open.back().at);
    return "";
}

unitTests:
using Calls = std::vector<Call>;
TEST("a good frame") { CHECK_EQ(checkFrame(Calls{ {"Begin"}, {"PushID"}, {"BeginTable", true}, {"EndTable"}, {"PopID"}, {"End"} }), std::string("")); }
TEST("collapsed window still needs End") { CHECK_EQ(checkFrame(Calls{ {"Begin", false}, {"End"} }), std::string("")); CHECK_EQ(checkFrame(Calls{ {"Begin", false} }), std::string("missing End for Begin at 0")); }
TEST("table that returned false") { CHECK_EQ(checkFrame(Calls{ {"Begin"}, {"BeginTable", false}, {"End"} }), std::string("")); CHECK_EQ(checkFrame(Calls{ {"Begin"}, {"BeginTable", false}, {"EndTable"}, {"End"} }), std::string("EndTable at 2 was called although BeginTable returned false")); }
TEST("missing PopID") { CHECK_EQ(checkFrame(Calls{ {"Begin"}, {"PushID"}, {"End"} }), std::string("End at 2 has no matching Begin")); }
TEST("wrong order") { CHECK_EQ(checkFrame(Calls{ {"Begin"}, {"BeginChild"}, {"End"}, {"EndChild"} }), std::string("End at 2 has no matching Begin")); }
TEST("end with nothing open") { CHECK_EQ(checkFrame(Calls{ {"End"} }), std::string("End at 0 has no matching Begin")); }
TEST("innermost missing end") { CHECK_EQ(checkFrame(Calls{ {"Begin"}, {"BeginMenu", true} }), std::string("missing EndMenu for BeginMenu at 1")); }
TEST("other calls are ignored") { CHECK_EQ(checkFrame(Calls{ {"Begin"}, {"Text"}, {"Button", false}, {"End"} }), std::string("")); }

